package app.bikriflow.mobile.data

enum class OrderStatus(val label: String) { NEW("New"), CONFIRMED("Confirmed"), PACKED("Packed"), SHIPPED("Shipped"), DELIVERED("Delivered"), COD_PENDING("COD pending"), PAID("Paid"), RETURNED("Returned"), CANCELLED("Cancelled"), FAILED("Failed delivery"); val isClosed: Boolean get() = this in setOf(PAID, RETURNED, CANCELLED, FAILED); val restoresStock: Boolean get() = this in setOf(RETURNED, CANCELLED, FAILED) }

data class Product(val id: Long = 0, val name: String, val sku: String = "", val variant: String = "", val salePrice: Double = 0.0, val costPrice: Double = 0.0, val stock: Int = 0, val lowStockAt: Int = 3, val active: Boolean = true)
data class OrderItem(val id: Long = 0, val orderId: Long = 0, val productId: Long? = null, val name: String, val variant: String = "", val quantity: Int = 1, val salePrice: Double = 0.0, val unitCost: Double = 0.0) { val lineRevenue: Double get() = salePrice * quantity; val lineCost: Double get() = unitCost * quantity }
data class Order(val id: Long = 0, val orderNo: String = "", val customerName: String, val phone: String = "", val address: String = "", val channel: String = "Facebook", val paymentMethod: String = "COD", val status: OrderStatus = OrderStatus.NEW, val items: List<OrderItem> = emptyList(), val customerDeliveryCharge: Double = 0.0, val courierCost: Double = 0.0, val packagingCost: Double = 0.0, val discount: Double = 0.0, val advance: Double = 0.0, val codFee: Double = 0.0, val otherExpense: Double = 0.0, val note: String = "", val createdAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis()) { val merchandiseTotal: Double get() = items.sumOf { it.lineRevenue }; val productCost: Double get() = items.sumOf { it.lineCost }; val revenue: Double get() = (merchandiseTotal + customerDeliveryCharge - discount).coerceAtLeast(0.0); val profit: Double get() = revenue - productCost - courierCost - packagingCost - codFee - otherExpense; val amountDue: Double get() = (revenue - advance).coerceAtLeast(0.0) }
data class CustomerSummary(val name: String, val phone: String, val orderCount: Int, val deliveredCount: Int, val returnedCount: Int, val lifetimeValue: Double, val lastOrderAt: Long)
data class DashboardMetrics(val todayOrders: Int = 0, val todaySales: Double = 0.0, val todayProfit: Double = 0.0, val pendingCod: Double = 0.0, val returns: Int = 0, val lowStockCount: Int = 0, val monthSales: Double = 0.0, val monthProfit: Double = 0.0)
